 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]

    # Solid lines in the background color can be empty panel interiors; only
    # non-background solid lines divide the grid into panels.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def spans(length, separators):
        result, start = [], 0
        for pos in separators + [length]:
            if start < pos:
                result.append((start, pos))
            start = pos + 1
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)

    panels = []
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            motif = {(r-r0, c-c0): grid[r][c]
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != background
                     and grid[r][c] not in separator_colors}
            panels.append((r0, r1, c0, c1, motif))
    if not panels:
        return [row[:] for row in grid]
    source = max(panels, key=lambda panel: len(panel[4]))
    sr0, sr1, sc0, sc1, motif = source
    if not motif:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r1-r0 != sr1-sr0 or c1-c0 != sc1-sc0:
                continue
            for (dr, dc), value in motif.items():
                out[r0+dr][c0+dc] = value
    return out
